<section class="panel form-panel narrow"><h2>Protege el acceso a tu cuenta</h2><p class="muted"><?=(int)$u['force_password']?'Para continuar, reemplaza tu contraseña inicial.':'Actualiza tu contraseña cuando lo necesites.'?></p><form method="post"><?=csrf()?><input type="hidden" name="action" value="password"><label>Contraseña actual<input name="current_password" type="password" autocomplete="current-password" required></label><label>Nueva contraseña<input name="new_password" type="password" autocomplete="new-password" minlength="8" maxlength="15" required><small>De 8 a 15 caracteres, con letras y números.</small></label><label>Confirmar nueva contraseña<input name="confirm_password" type="password" autocomplete="new-password" required></label><button class="button">Guardar contraseña</button></form></section>
